class AsyncContaApi(AsyncKonApi):
    """kon-conta

    Motor de Libro Mayor General (General Ledger Engine) con partida doble, multidivisa, plantillas de asientos, metadata JSONB y soporte para contabilidad legal (trust accounting y disbursements).
    """

    kon = "kon-conta"

    async def aplicar_plantilla(self, *, id: Union[str, int], body: AplicarPlantillaBody, request_options: Optional[RequestOptions] = None) -> Outcome[AplicarPlantillaResult]:
        """Preview a journal template

        Computes the ledger lines a template would produce for the given variables and metadata, without writing anything (create the journal with crear-asiento). 404 if the template does not exist; 400 if a formula, a required metadata field or an account code fails. Read access to the ledger.

        REST: `POST /api/conta/templates/{id}/apply` · scope `kon:conta:aplicar-plantilla`
        not idempotent (an Idempotency-Key is sent automatically) · MCP tool `conta__aplicar-plantilla`
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
        """
        return await self._call(OPERATIONS["aplicar-plantilla"], {"id": id}, body, request_options)

    async def borrar_asiento(self, *, id: Union[str, int], request_options: Optional[RequestOptions] = None) -> Outcome[BorrarAsientoResult]:
        """Delete a draft journal

        Deletes a DRAFT journal and its lines. A posted journal is a 409: reverse it instead (revertir-asiento). 404 if it does not exist. Write access to the ledger.

        REST: `DELETE /api/conta/journals/{id}` · scope `kon:conta:borrar-asiento`
        idempotent (safe to retry) · sensitive: may come back as a proposal pending human approval · MCP tool `conta__borrar-asiento`
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
        """
        return await self._call(OPERATIONS["borrar-asiento"], {"id": id}, None, request_options)

